mapper.select:
select inst.BUSINESS_KEY_ as businessKey, max(task.ID_) as taskId, inst.PROC_DEF_KEY_ as category, max(task.NAME_) as taskName, task.PROC_INST_ID_ as processInstanceId FROM act_hi_taskinst task join act_hi_procinst inst on task.PROC_INST_ID_=inst.ID_ join act_ru_identitylink link on task.ID_ = link.TASK_ID_
inst.END_TIME_ is null
AND (inst.START_USER_ID_=#{userId} or task.ASSIGNEE_=#{userId})
AND inst.PROC_DEF_KEY_ = #{category}
group by inst.BUSINESS_KEY_,inst.PROC_DEF_KEY_,task.PROC_INST_ID_;

SELECT pro.PROC_DEF_KEY_ as cateKey,count(distinct pro.BUSINESS_KEY_) as num
FROM ACT_HI_TASKINST task
inner join act_hi_procinst pro on pro.PROC_INST_ID_ =task.PROC_INST_ID_
WHERE task.DELETE_REASON_ = 'completed'  AND task.END_TIME_ is not null
AND task.ASSIGNEE_ = #{assignee}

    AND task.START_TIME_>= #{startTime}


    AND task.END_TIME_<= #{endTime}

GROUP BY pro.PROC_DEF_KEY_

SELECT DISTINCT pro.BUSINESS_KEY_
FROM ACT_HI_TASKINST task
INNER JOIN ACT_HI_PROCINST pro ON pro.PROC_INST_ID_ = task.PROC_INST_ID_
WHERE task.DELETE_REASON_ = 'completed' AND task.END_TIME_ is not null
AND task.ASSIGNEE_ = #{assignee}
AND pro.PROC_DEF_KEY_ = #{category}

    AND task.START_TIME_ >= #{startTime}


    AND task.END_TIME_ <= #{endTime}

mapper.sql:
from ACT_RU_TASK task INNER JOIN ACT_RE_PROCDEF pd ON task.PROC_DEF_ID_ = pd.ID_ INNER JOIN ACT_RU_EXECUTION exe ON exe.PROC_DEF_ID_ = pd.ID_ AND exe.PARENT_ID_ is null AND exe.ID_=task.PROC_INST_ID_ AND exe.PROC_INST_ID_=task.PROC_INST_ID_
task.SUSPENSION_STATE_ = 1
AND task.ASSIGNEE_ = #{assignee}
AND pd.KEY_ = #{category}
